<?php
 namespace OSS\Model; use OSS\Core\OssException; class WormConfig implements XmlConfig { public function parseFromXml($strXml) { $xml = simplexml_load_string($strXml); if (isset($xml->WormId)) { $this->wormId = strval($xml->WormId); } if (isset($xml->State)) { $this->state = strval($xml->State); } if (isset($xml->RetentionPeriodInDays)) { $this->day = intval($xml->RetentionPeriodInDays); } if (isset($xml->CreationDate)) { $this->creationDate = strval($xml->CreationDate); } } public function serializeToXml() { throw new OssException("Not implemented."); } public function __toString() { return $this->serializeToXml(); } public function getWormId() { return $this->wormId; } public function getState() { return $this->state; } public function getDay() { return $this->day; } public function getCreationDate() { return $this->creationDate; } private $wormId = ''; private $state = ''; private $creationDate = ''; private $day = 0; }